import {CHARACTERS,CHAPTERS,SOURCES} from './content.js?v=1.1.0-r2';
import {createRun,applyChoice,selectCompanion,manage,beginBattle,actBattle,finishChapter,getEnding,getDailySeed,MANAGEMENT_ACTIONS,FORMATIONS,COMPANION_ABILITIES,setFormation,getCompanionAbility,useCompanionAbility,getDailyModifier} from './engine.js?v=1.1.0-r2';
import {portrait} from './portraits.js?v=1.1.0-r2';
import {mountScene,updateScene,destroyScene,pauseScene} from './scene.js?v=1.1.0-r2';
import {challengeURL,shareText,downloadPoster} from './share.js?v=1.1.0-r2';
import {initAudio,soundEnabled,chime,setAudioScene,setAudioPaused,getAudioSettings,setAudioSetting,getAudioStatus} from './audio.js?v=1.1.0-r2';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={people:'民心',grain:'粮草',army:'军备',prestige:'声望'},lanes=['左路','中路','右路'],intents={rush:'突进',fortify:'固守',ambush:'伏击'};
const phaseNames={companion:'故人相逢',story:'风云抉择',manage:'战前筹备',battle:'运筹帷幄',review:'史册回望',ending:'人生回响'};
const eligibleCompanions=new Set(CHAPTERS.flatMap(c=>[c.lead,...c.companions]));
const SAVE='ming-chronicle-run-v1',PROFILE='ming-chronicle-profile-v1';
let viewedRecord=null,paused=false,audioStatusTimer=null,posterURL=null;
let saveAvailable=true, toastTimer, actionLocked=false, page='home',run=read(SAVE,null),profile=read(PROFILE,{runs:[],collected:[]});
if(!isRun(run))run=null;
if(!Array.isArray(profile?.runs)||!Array.isArray(profile?.collected))profile={runs:[],collected:[]};
profile.runs=profile.runs.filter(s=>isRun(s)&&s.phase==='ending');
profile.collected=profile.collected.filter(id=>CHARACTERS.some(c=>c.id===id));
const challenge=new URL(location.href).searchParams.get('seed');const challengeSeed=challenge&&/^[a-zA-Z0-9_-]{1,60}$/.test(challenge)?challenge:null;
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{saveAvailable=false;return fallback;}}
function isRun(s){
 if(!s||s.version!==1||!Number.isInteger(s.chapter)||s.chapter<0||s.chapter>6||!Number.isInteger(s.event)||s.event<0||s.event>3||!Object.hasOwn(phaseNames,s.phase))return false;
 if(!s.stats||!Object.keys(names).every(k=>Number.isFinite(s.stats[k])&&s.stats[k]>=0&&s.stats[k]<=100)||!s.tags||!['仁心','谋略','胆识'].every(k=>Number.isFinite(s.tags[k]))||!s.bonds||!Array.isArray(s.journal)||!s.journal.every(e=>e&&typeof e.text==='string')||!Array.isArray(s.results)||!Array.isArray(s.companions)||!Number.isFinite(s.rng)||!Number.isFinite(s.wins))return false;
 if(s.phase==='ending')return s.chapter===6&&s.results.length===6&&s.results.every(r=>r&&Number.isInteger(r.chapter)&&r.chapter>=0&&r.chapter<6)&&s.companions.every(c=>c&&typeof c.id==='string');
 if(s.chapter>=6||s.phase==='story'&&s.event>=CHAPTERS[s.chapter].events.length)return false;
 if(['battle','review'].includes(s.phase)&&(!s.battle||!Number.isFinite(s.battle.hp)||!Number.isFinite(s.battle.enemyHP)||!Array.isArray(s.battle.log)||!Array.isArray(s.battle.laneHP)||s.battle.laneHP.length!==3||!Object.hasOwn(intents,s.battle.intent)))return false;
 if(s.phase==='review'&&!s.battle.done)return false;
 return true;
}
function save(){try{if(run)localStorage.setItem(SAVE,JSON.stringify(run));localStorage.setItem(PROFILE,JSON.stringify(profile));}catch{saveAvailable=false;toast('浏览器未允许存档，本次进度仅在当前页面保留。');}}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function char(id){return CHARACTERS.find(c=>c.id===id)||CHARACTERS[0];}
function footer(){return `<footer><span class="footer-note">历史人物 · 原创对白与分支演绎<br>给每一个曾为历史热血、为故人动容的人。</span><span><button data-page="records">我的人生</button> · <button data-page="sources">史料与创作说明</button> · <button data-action="help">游玩指南</button><br>LINVERSE / 故人长卷</span></footer>`;}
function header(){return `<header><button class="brand" data-page="home" aria-label="返回长卷首页"><span class="seal">明</span><span><span class="brand-main">故人长卷</span><small>A MING DYNASTY STORY</small></span></button><nav aria-label="主要导航">${[['home','长卷行旅'],['characters','故人录'],['records','我的人生'],['sources','史料馆']].map(([key,label])=>`<button data-page="${key}" class="${page===key?'active':''}">${label}</button>`).join('')}</nav><div class="header-tools"><span class="save-label"><i class="save-light"></i>${saveAvailable?'行囊已备好':'存档未启用'}</span><button class="icon-button ${soundEnabled()?'music-on':''}" data-action="sound" aria-label="音乐与音效设置" title="音乐与音效设置">${soundEnabled()?'♪':'♩'}</button><button class="icon-button" data-action="help" aria-label="游玩指南">?</button></div></header>`;}
function landscape(i){const city=[1,3,5].includes(i);return `<svg viewBox="0 0 380 140" preserveAspectRatio="xMidYMax slice" aria-hidden="true"><circle cx="290" cy="36" r="21" fill="#f3e2ac" opacity=".7"/><path d="M-30 113L70 31l60 56 65-73 86 85 50-61 70 60v70H0z" fill="#788c76" opacity=".22"/><path d="M0 132l80-59 51 23 83-52 83 67 79-29 30 76H0" fill="#607e6c" opacity=".26"/><path d="M0 122q100-13 200 4t180-2v30H0z" fill="#65857a" opacity=".26"/>${city?'<path d="M80 114V83h213v31" fill="#b8b495"/><path d="M70 83h234l-24-10H95z" fill="#566859"/><path d="M145 105V52h100v53" fill="#ad7359"/><path d="M130 55h129l-27-16h-74z" fill="#526958"/><path d="M149 37h92l-19-11h-56z" fill="#677a62"/><path d="M184 111V78q13-10 26 0v33" fill="#5e6654"/><path d="M92 96h7m20 0h7m142 0h7" stroke="#69755c" stroke-width="6"/>':'<path d="M159 113h133l-21 16h-90z" fill="#745e42"/><path d="M204 109V24m42 85V38" stroke="#695d40" stroke-width="3"/><path d="M199 29q-38 34-36 67h37zm10-1q30 30 29 64h-29zm42 16q26 28 24 57h-24z" fill="#d2ad6b"/><path d="M170 56h29m-34 17h33m13-16h20m-21 17h25" stroke="#a17f4f" opacity=".5"/>'}<path d="M15 139q14-28 35-19t36 14m218 5q20-32 42-18t46 15" fill="#466552" opacity=".55"/></svg>`;}
function home(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">一卷山河 · 故人再逢</div><h1>再入大明。<br>与故人，<em>重逢。</em></h1><p class="lead">翻过的，是三百年风云。<br>放不下的，是那些有血有肉的人。</p><div class="hero-buttons"><button class="btn primary" data-action="${run&&run.phase!=='ending'?'continue':'start'}">${run&&run.phase!=='ending'?'续写我的长卷':'入卷，写我的人生'} <span>→</span></button><button class="btn ghost" data-action="daily">${challengeSeed?'接受好友同题':'今日同题'} <span>↗</span></button></div><p class="hero-note">剧情抉择 / 阵型布策 / 故人绝技 / 三路战役</p></div><div class="hero-stamp">山河依旧　故人如昨</div><div class="hero-bottom">六幕历史 · 一卷人生</div></section><div class="container"><div class="intro-strip">${[['卷','从历史里，入戏','六个时代 · 十八次抉择'],['友','与故人，并肩','十二位人物 · 不同的同行'],['策','每一步，有回响','经营资源 · 布阵破局'],['签','把人生，寄给朋友','同题挑战 · 结局人生签']].map(a=>`<div class="intro-item"><span class="intro-glyph">${a[0]}</span><div><strong>${a[1]}</strong><small>${a[2]}</small></div></div>`).join('')}</div><div class="section-heading"><div><h2>一卷三百年，六次相逢。</h2><p>从鄱阳湖的一场风，到万历朝的一盏灯。</p></div><button class="text-link" data-action="help">如何入卷 →</button></div><div class="chapter-grid">${CHAPTERS.map((c,i)=>`<button class="chapter-card" data-chapter="${i}"><div class="chapter-land t${i}">${landscape(i)}<span class="chapter-no">CHAPTER 0${i+1}</span><span class="chapter-label">${['布衣逐鹿','靖难风云','帆向沧海','守住京城','东南烽火','万历新政'][i]}</span></div><div class="chapter-info"><div class="chapter-meta">${esc(c.year)} · ${esc(c.place)}</div><div class="chapter-title"><h3>${esc(c.title)}</h3><span class="round-arrow">↗</span></div><p>${esc(c.subtitle)}</p></div></button>`).join('')}</div><div class="home-bottom"><div class="friends-banner"><div><h3>史书有名，故人有情。</h3><p>朱元璋、郑和、于谦……与熟悉的名字，再走一程。</p><button class="text-link" data-page="characters">翻开故人录 →</button></div><div class="portrait-stack">${[0,1,7,8].map(i=>`<span>${portrait(CHARACTERS[i],54)}</span>`).join('')}</div></div><div class="daily-banner"><div><h3>同一困局，你会如何选？</h3><p>${esc(getDailyModifier(getDailySeed()).title)} · 每日局势，邀朋友同题破局。</p><button class="text-link" data-action="daily">展开今日同题 ↗</button></div><span class="daily-symbol">签</span></div></div></div>`;}
function characters(){return `<div class="container"><div class="page-intro"><div class="eyebrow">故人录 · ${profile.collected.filter(id=>eligibleCompanions.has(id)).length} / ${eligibleCompanions.size} 已同行</div><h1>不是名字，是故人。</h1><p>十二位史册人物，十一位可同行。身份与时代来自历史，技能与对白为原创演绎。</p></div><div class="character-grid">${CHARACTERS.map(c=>`<article class="character-card"><span class="bond">${!eligibleCompanions.has(c.id)?'史册人物':profile.collected.includes(c.id)?'✦ 已结缘':'待相逢'}</span>${portrait(c,112)}<h3>${esc(c.name)}</h3><div class="role">${esc(c.role)} · ${esc(c.years)}</div><span class="tag">${esc(c.trait)}</span><p class="bio">${esc(c.bio)}</p>${eligibleCompanions.has(c.id)?`<div class="skill-note">同行助益 · ${names[c.skill.stat]} +${c.skill.amount}</div><div class="codex-ability"><b>${esc(COMPANION_ABILITIES[c.id]?.name||'故人助阵')}</b><p>${esc(COMPANION_ABILITIES[c.id]?.description||'蓄势后施展同行之策。')}</p></div>`:'<div class="codex-ability"><b>建文一朝 · 史册对照</b><p>本卷保留其历史身份，不作为朱棣阵营的同行之人。</p></div>'}</article>`).join('')}</div></div>`;}
function sources(){return `<div class="container"><div class="page-intro"><div class="eyebrow">史料馆</div><h1>故事有来处，选择有边界。</h1><p>记得故事的温度，也分得清史实与想象。</p></div><div class="notice">本作保留《明朝那些事儿》中出现的真实历史人物，以公开史料为依据创作对白、抉择和卡通形象。六幕是历史片段选集，并非原著全本或官方改编。每幕结算的「史实回望」与玩家战报分开呈现。<br>现代原著全本尚未下载；可通过下方正版入口阅读。本作不提供原著全文。</div><div class="sources-list">${CHAPTERS.map(c=>`<article class="source-card"><h3>${esc(c.title)}</h3><p>${esc(c.history)}</p><a href="${esc(c.source.url)}" target="_blank" rel="noopener noreferrer">${esc(c.source.title)} ↗</a></article>`).join('')}<article class="source-card"><h3>《明朝那些事儿》正版阅读</h3><p>当年明月著。完整阅读需依平台的购买、会员或借阅条件进行；阅读权限不等于可导出的文本文件。</p><a href="https://www.dedao.cn/ebook/detail?id=Jjrvne28LQ2OjoRqkgdnmJX6NADGlWxKvB0x1KvbBz97eaMP4VZrpEYy5VB6adNX" target="_blank" rel="noopener noreferrer">得到 · 全七册 ↗</a></article><article class="source-card"><h3>长卷的创作</h3><p>主视觉为原创生成插画，卡通肖像为原创绘制，背景与战役由 Phaser 呈现。没有使用影视演员剧照或原著插图。所有战斗为抽象策略演练。</p><a href="vendor/PHASER-LICENSE.txt" target="_blank">Phaser 3.90 · MIT 许可 ↗</a></article></div></div>`;}
function stats(){return `<div class="stats">${Object.entries(names).map(([key,label])=>`<div><div class="stat-line"><span>${label} <small>${{people:'众望',grain:'补给',army:'战力',prestige:'名望'}[key]}</small></span><b>${run.stats[key]}</b></div><div class="meter"><i style="width:${run.stats[key]}%;background:${run.stats[key]<25?'#b45b40':key==='people'?'#708770':key==='army'?'#b68155':'#b69e61'}"></i></div></div>`).join('')}</div>`;}
function effects(e){return Object.entries(e||{}).filter(([,v])=>v).map(([key,value])=>`<span class="${value<0?'negative':''}">${names[key]||esc(key)} ${value>0?'+':''}${value}</span>`).join('');}
function game(){if(!run){page='home';return home();}if(run.phase==='ending')return endingView(run);const c=CHAPTERS[run.chapter],lead=char(c.lead);return `<main class="game-shell"><div class="game-top"><div><small>${run.mode==='daily'?'同题挑战':'长卷行旅'} · ${esc(run.seed)}</small><h1><span class="chapter-counter">0${run.chapter+1}</span>${esc(c.title)}</h1></div><div class="game-actions"><button class="btn small" data-action="pause">暂停</button><button class="btn small" data-action="save-exit">存卷</button><button class="btn small" data-action="help">玩法</button></div></div>${run.dailyModifier?`<div class="daily-rules"><b>今日局势 · ${esc(run.dailyModifier.title)}</b><span>${esc(run.dailyModifier.description)}</span></div>`:''}<div class="timeline">${CHAPTERS.map((ch,i)=>`<span class="${i<run.chapter?'past':i===run.chapter?'current':''}">${esc(ch.title)}</span>`).join('')}</div><div id="stats">${stats()}</div><div class="game-layout"><div><div class="scene-panel"><div class="scene-top"><span>${esc(c.year)} · ${esc(c.place)}</span><span>${phaseNames[run.phase]}</span></div><div id="scene" class="scene-frame" role="img" aria-label="${esc(c.title)}的三路战场示意"></div><div class="scene-caption">${portrait(lead,60)}<div><h3>${esc(lead.name)} <span class="tag">${esc(lead.role)}</span></h3><p>“${esc(lead.quote)}”</p></div></div></div><div class="journal"><h4>行旅手记</h4>${run.journal.slice(-3).map(e=>`<p>· ${esc(e.text)}</p>`).join('')||'<p>长卷初启，第一笔由你来落。</p>'}</div></div><div id="story" class="story-panel ${run.phase==='battle'?'in-battle':''}">${storyPanel(c)}</div></div></main>`;}
function contextualLine(){if(run.stats.people<35)return '城里的议论渐渐多了起来。百姓的信任，正从你的指间流走。';if(run.stats.grain<25)return '粮仓的余粮已经不多，接下来的每一步都得掂量。';if(run.stats.people>80)return '一路行来，百姓愿意为你留一盏灯。这份信任也成了你的底气。';return '';}
function storyPanel(c){if(run.phase==='companion')return `<div class="story-kicker">第 ${run.chapter+1} 幕 / 故人相逢</div><h2>${esc(c.title)}，你与谁同行？</h2><p class="story-text">${esc(c.intro)}</p><div class="companion-list">${[...new Set([c.lead,...c.companions])].map(id=>{const p=char(id);return `<button class="companion" data-companion="${esc(id)}">${portrait(p,58)}<div><h3>${esc(p.name)}</h3><small>${esc(p.trait)}</small><div class="skill">${names[p.skill.stat]} +${p.skill.amount}</div>${run.ruleset===2?`<div class="ability-preview">${esc(COMPANION_ABILITIES[p.id]?.name||'故人助阵')}</div>`:''}</div></button>`;}).join('')}</div><p class="under-note">每幕选一位同行之人，即刻获得助益并记入故人录。</p>`;
 if(run.phase==='story'){const e=c.events[run.event],context=contextualLine();return `<div class="story-kicker">风云抉择 / ${run.event+1} OF ${c.events.length} · ${esc(char(e.speaker).name)}</div><h2>${esc(e.title)}</h2><p class="story-text">${esc(e.text)}</p>${context?`<p class="game-hint">${esc(context)}</p>`:''}<div class="choice-list">${e.choices.map((ch,i)=>`<button class="choice" data-choice="${i}"><strong><span class="choice-letter">${'ABC'[i]}</span>${esc(ch.label)}</strong><span class="tag">${esc(ch.tag)}</span><p>${esc(ch.detail)}</p><div class="effects">${effects(ch.effects)}</div></button>`).join('')}</div><p class="under-note">选择改变资源与人生倾向，结局由一路的你共同写成。</p>`;}
 if(run.phase==='manage')return `<div class="story-kicker">战前筹备 / 余 ${2-run.management} 次</div><h2>先安后方，再赴风云。</h2><p class="story-text">${esc(c.mission.desc)}</p><div class="manage-grid">${Object.entries(MANAGEMENT_ACTIONS).map(([k,v])=>`<button class="manage-card" data-manage="${k}" ${run.management>=2||Object.entries(v.cost).some(([stat,n])=>run.stats[stat]<n)?'disabled':''}><strong>${v.name}</strong><small>${Object.entries(v.effects).map(([stat,n])=>`${names[stat]} ${n>0?'+':''}${n}`).join(' · ')}</small></button>`).join('')}</div>${run.ruleset===2?formationPanel():''}<p class="game-hint">军备影响战力，粮草支持齐射；行军也需补给。筹备可以跳过。</p><button class="btn primary" data-action="battle">进入${esc(c.mission.title)} →</button>`;
 if(run.phase==='battle'){const b=run.battle;return `<div class="story-kicker">策略演练 / ${esc(c.mission.title)}</div><div class="battle-status"><div><small>我方阵线</small><br><b>${b.hp}<small> / ${b.maxHp}</small></b></div><div><small>第 ${b.turn} / 8 回合</small></div><div><small>${esc(c.mission.enemyName)}</small><br><b>${b.enemyHP}<small> / ${b.maxEnemyHP}</small></b></div></div>${objectivePanel(b)}<div class="enemy-intent">斥候来报：敌方将于<strong>${lanes[b.lane]}${intents[b.intent]}</strong>。${b.wind!==undefined?`本回合顺风：${lanes[b.wind]}。`:''}</div><p class="game-hint">${esc(b.terrainRule||'选中来敌一路，再用克制战术迎击。')}</p><div class="lane-picker" aria-label="选择战线">${lanes.map((l,i)=>`<button data-lane="${i}" aria-pressed="${run.selectedLane===i}" class="${run.selectedLane===i?'selected':''}">${l} · ${b.laneHP[i]}</button>`).join('')}</div><div class="tactics">${[['strike','强攻','稳定伤害，无额外消耗'],['guard','坚守','克制突进 · 大幅减损'],['flank','迂回','克制固守 · 绕击破阵'],['volley','齐射',`克制伏击 · 消耗${b.volleyCost??(b.terrain==='sea'?6:5)}粮草`]].map(([k,n,d])=>`<button class="tactic" data-tactic="${k}" ${k==='volley'&&run.stats.grain<(b.volleyCost??(b.terrain==='sea'?6:5))?'disabled':''}><strong>${n}</strong><small>${d}</small></button>`).join('')}</div>${abilityPanel()}<div class="combat-log" role="log">${b.log.slice(-2).map(l=>`<p>${esc(l.text)}</p>`).join('')||'<p>选路后下达战术，八回合内破局；蓄力两次可施展故人技。</p>'}</div>`;}
 if(run.phase==='review'){const b=run.battle;return `<div class="story-kicker">此幕落笔 / 玩家演绎</div><h2>${b.victory?'这一程，守住了。':'胜负之外，还有故人。'}</h2><p class="story-text">${b.victory?'风声渐息，你和同行的人都留住了这一刻。下一段历史，还在远方等着你。':'此役留下了遗憾，但长卷尚未合上。带着这次抉择，继续向前。'}</p><div class="review-score"><span>${b.victory?'告捷':'未竟'} · ${b.turn} 回合<br><small>剩余阵线 ${b.hp} / ${b.maxHp}</small></span><strong>${run.wins}<small style="font-size:16px"> 胜</small></strong></div>${b.objective?`<div class="objective-summary ${b.objective.complete?'complete':''}">${b.objective.complete?'✦ 额外目标达成':'○ 额外目标未达成'} · ${esc(b.objective.title)}</div>`:''}<div class="history-box"><strong>史实回望 · 不随玩家选择改变</strong>${esc(c.history)}<br><a href="${esc(c.source.url)}" target="_blank" rel="noopener noreferrer">查阅 ${esc(c.source.title)} ↗</a></div><button class="btn primary" data-action="next">${run.chapter===5?'合上长卷，领取人生签':'走向下一幕'} →</button>${run.battleCheckpoint?'<button class="btn retry-button" data-action="retry-battle">重试本幕</button>':''}`;}return '';}
function endingView(s){const e=getEnding(s),person=char(e.characterId);return `<div class="container"><div class="result-wrap"><div class="result-poster"><div class="eyebrow" style="justify-content:center">我的大明人生签 · 六幕回响</div>${portrait(person,125)}<h1>${esc(e.title)}</h1><p class="subtitle">${esc(e.subtitle)}</p><p class="result-text">${esc(e.text)}</p><div class="result-score">${e.score}</div><div class="result-stats"><span>人生回响</span><span>${s.wins} / 6 幕告捷</span><span>同行 ${Object.keys(s.bonds).length} 位故人</span>${s.ruleset===2?`<span>目标 ${s.results.filter(r=>r.objectiveComplete).length} / 6</span>`:''}</div><div class="result-tags">${Object.entries(s.tags).map(([t,n])=>`<span class="tag">${t} ${n}</span>`).join('')}</div><div class="result-stats">${Object.entries(names).map(([k,n])=>`<span>${n} ${s.stats[k]}</span>`).join('')}</div></div><div class="result-controls"><button class="btn primary" data-action="poster">保存人生签 ↓</button><button class="btn dark" data-action="share">邀请朋友同题 ↗</button><button class="btn" data-action="start">再走一种人生</button></div><p class="game-hint">人生签可直接分享；好友链接能否访问取决于网站的分享设置。</p><div class="chapter-results">${s.results.map(r=>`<div class="mini-result">${r.victory?'✦':'○'} ${esc(CHAPTERS[r.chapter]?.title)}<small>${r.turns} 回合 · ${r.victory?'告捷':'未竟'}${r.objectiveComplete?' · ✦目标':''} · ${esc(s.companions.find(p=>p.chapter===r.chapter)?.name||'')}</small></div>`).join('')}</div><div class="notice" style="text-align:left">长卷止于几个交汇的时代，明史却继续向前。1644 年，明朝在北京的统治终结。这枚人生签记录你的选择，不替历史改变结局，也不代表对历史人物的评判。</div></div></div>`;}
function records(){if(!profile.runs.length)return `<div class="container"><div class="empty-state"><div class="eyebrow" style="justify-content:center">我的人生</div><h2>长卷留白，等你落笔。</h2><p>完成六幕后，你的人生签会保存在这里。</p><button class="btn primary" data-action="${run&&run.phase!=='ending'?'continue':'start'}">${run&&run.phase!=='ending'?'续写长卷':'展开第一卷'} →</button></div></div>`;return `<div class="container"><div class="page-intro"><div class="eyebrow">我的人生 / ${profile.runs.length} 卷已落笔</div><h1>你走过的，每一种人生。</h1><p>行旅与故人仅保存在当前浏览器，换设备不会自动同步。</p></div><div class="sources-list">${profile.runs.slice().reverse().map((r,i)=>{const e=getEnding(r);return `<article class="source-card"><span class="tag">${esc(r.mode==='daily'?'同题挑战':'长卷行旅')}</span><h3 style="margin-top:15px">${esc(e.title)}</h3><p>${esc(e.subtitle)} · 人生回响 ${e.score} · ${r.wins} 幕告捷</p><button class="text-link" data-record="${profile.runs.length-1-i}">重看人生签 →</button></article>`;}).join('')}</div></div>`;}
function modal(html){destroyFocusBeforeDialog();const m=$('#modal');m.innerHTML=`<button class="modal-close" data-action="close-modal" aria-label="关闭">×</button>${html}`;m.showModal();}
function destroyFocusBeforeDialog(){if($('#modal').open)$('#modal').close();}
function closeModal(){$('#modal').close(); if(paused){paused=false;setAudioPaused(false);pauseScene(false);}clearInterval(audioStatusTimer);audioStatusTimer=null;if(posterURL){URL.revokeObjectURL(posterURL);posterURL=null;}}
function help(){modal(`<h2>如何走进这卷历史</h2><p><b>1. 与故人同行。</b>每幕选择一位历史人物，获得资源助益并收进故人录。</p><p><b>2. 做三次抉择。</b>选项会直接改变民心、粮草、军备、声望，以及你的仁心、谋略、胆识倾向。</p><p><b>3. 筹备后上阵。</b>每幕可经营两次。战役先选一路，再下战术：坚守克突进，迂回克固守，齐射克伏击。选准敌方来路还能增伤减损。</p><p><b>4. 阵型、故人技与战场目标。</b>新长卷可选均衡、强攻或固守阵型；行动两次蓄力后，每场可用一次故人技。完成额外目标增加人生回响，失败可重试或继续。旧存档保留原规则。</p><p><b>5. 合卷留签。</b>六幕后得到人生签。下载图片或复制同题链接，与朋友比较选择。每日题按北京时间更新，相同种子、相同选择会得到相同结果。</p><p>快捷键：数字 1/2/3 选路，Q/W/E/R 对应强攻/坚守/迂回/齐射，F 施展故人技，Esc 暂停。音乐默认开启，首次交互后自动播放；右上角可分别调配乐与音效。</p><p>进度自动保存于本浏览器。史实回望与玩家演绎分开呈现。</p><button class="btn primary" data-action="close-modal">我已明白，入卷 →</button>`);}
function start(mode='story',force=false){if(run&&run.phase!=='ending'&&!force){modal(`<h2>另起一卷？</h2><p>当前行囊停在「${esc(CHAPTERS[run.chapter].title)}」。另起一卷会替换这份未完成进度，已结缘故人与已完成人生签会保留。</p><button class="btn primary" data-new="${mode}">另起一卷</button> <button class="btn" data-action="continue">继续旧卷</button>`);return;}closeModal();run=createRun(mode==='daily'?(challengeSeed||getDailySeed()):`journey-${Date.now().toString(36)}`,mode);run.runId=`run-${Date.now().toString(36)}`;run.selectedLane=1;page='game';save();render();}
function recordEnding(){if(run.phase!=='ending')return;const key=run.runId||run.seed+'-'+JSON.stringify(run.journal);if(!profile.runs.some(s=>s.recordKey===key)){const copy=JSON.parse(JSON.stringify(run));copy.recordKey=key;profile.runs.push(copy);profile.runs=profile.runs.slice(-20);}save();}
function render(keepScroll=false){const scroll=window.scrollY;destroyScene();const content=page==='home'?home():page==='characters'?characters():page==='sources'?sources():page==='records'?records():page==='record'?endingView(viewedRecord):game();$('#app').innerHTML=header()+content+footer();syncAudio();if(page==='game'&&run&&run.phase!=='ending'){try{mountScene($('#scene'),CHAPTERS[run.chapter],run,selectLane);}catch(e){$('#scene').innerHTML='<p style="padding:30px">战场画面暂未加载，右侧策略按钮仍可正常游玩。</p>';console.error(e);}}if(!keepScroll)window.scrollTo(0,0);else window.scrollTo(0,scroll);}
function refreshGame(){syncAudio();if(!run||run.phase==='ending'){render(true);return;}$('#stats').innerHTML=stats();$('#story').innerHTML=storyPanel(CHAPTERS[run.chapter]);$('#story').classList.toggle('in-battle',run.phase==='battle');const phase=$('.scene-top span:last-child');if(phase)phase.textContent=phaseNames[run.phase];const j=$('.journal');if(j)j.innerHTML='<h4>行旅手记</h4>'+run.journal.slice(-3).map(e=>`<p>· ${esc(e.text)}</p>`).join('');updateScene(run);}
function selectLane(lane){if(paused||run?.phase!=='battle')return;run.selectedLane=lane;save();refreshGame();}
function perform(fn){if(actionLocked||paused)return;actionLocked=true;try{const result=fn();if(result.ok){save();chime(result.done?(result.victory?'win':'lose'):result.type==='ability'?'win':result.tactic==='guard'?'guard':result.damage!==undefined?'hit':'choice');refreshGame();if(result.damage!==undefined||result.ability)showCombatFeedback(result);if(result.effects)showResourceFeedback(result.effects);}else toast(result.message||'这一步暂不可执行。');}catch(e){console.error(e);toast('这一步未能完成，已保留当前进度。');}finally{setTimeout(()=>actionLocked=false,230);}}
async function doShare(){const current=page==='record'?viewedRecord:run;const e=getEnding(current),text=shareText(current,e);try{await navigator.clipboard.writeText(text);toast('战报与同题链接已复制，可以发给朋友了。');}catch{modal(`<h2>邀请朋友，同题不同人生</h2><p>复制这条链接，朋友会从相同的种子开始。</p><input class="share-input" readonly value="${esc(challengeURL(current))}" aria-label="好友挑战链接"><p>${esc(e.title)} · 人生回响 ${e.score}</p><button class="btn primary" data-action="select-link">选中链接</button>`);}}
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.page){page=b.dataset.page;render();return;}
 if(b.dataset.chapter!==undefined){const c=CHAPTERS[+b.dataset.chapter],p=char(c.lead);modal(`<div class="chapter-dialog-portrait">${portrait(p,95)}</div><div class="eyebrow">第 ${+b.dataset.chapter+1} 幕 · ${esc(c.year)}</div><h2>${esc(c.title)}</h2><p>${esc(c.intro)}</p><div class="history-box"><strong>本幕玩法</strong>${esc(c.mission.title)} · ${esc(c.mission.desc)}</div><p>沿着六幕长卷前进，与当时的故人并肩。已完成的篇章会留在你的行旅记录中。</p><button class="btn primary" data-action="${run&&run.phase!=='ending'?'continue':'start'}">${run&&run.phase!=='ending'?'继续我的长卷':'从第一幕展开'} →</button>`);return;}
 if(b.dataset.companion){perform(()=>{const c=char(b.dataset.companion),r=selectCompanion(run,c);if(r.ok&&!profile.collected.includes(c.id))profile.collected.push(c.id);return r;});return;}
 if(b.dataset.choice!==undefined){perform(()=>applyChoice(run,CHAPTERS[run.chapter],CHAPTERS[run.chapter].events[run.event],+b.dataset.choice));return;}
 if(b.dataset.formation){perform(()=>setFormation(run,b.dataset.formation));return;}
 if(b.dataset.manage){perform(()=>manage(run,b.dataset.manage));return;}
 if(b.dataset.lane!==undefined){selectLane(+b.dataset.lane);return;}
 if(b.dataset.tactic){perform(()=>actBattle(run,b.dataset.tactic,run.selectedLane??1));return;}
 if(b.dataset.new){start(b.dataset.new,true);return;}
 if(b.dataset.record!==undefined){viewedRecord=JSON.parse(JSON.stringify(profile.runs[+b.dataset.record]));page='record';render();return;}
 switch(b.dataset.action){case'start':start();break;case'daily':start('daily');break;case'continue':closeModal();page='game';render();break;case'help':help();break;case'pause':pauseGame();break;case'ability':perform(()=>useCompanionAbility(run));break;case'close-modal':closeModal();break;case'save-exit':closeModal();save();page='home';render();toast('行囊已收好，下次回来继续。');break;case'sound':audioSettings();break;case'battle':perform(()=>{delete run.battleCheckpoint;const checkpoint=JSON.parse(JSON.stringify(run));const r=beginBattle(run,CHAPTERS[run.chapter]);if(r.ok)run.battleCheckpoint=checkpoint;return r;});break;case'retry-battle':if(run?.battleCheckpoint){const checkpoint=JSON.parse(JSON.stringify(run.battleCheckpoint));run=checkpoint;run.battleCheckpoint=JSON.parse(JSON.stringify(checkpoint));beginBattle(run,CHAPTERS[run.chapter]);save();render();}break;case'next':if(actionLocked)return;{const r=finishChapter(run);if(r.ok){delete run.battleCheckpoint;recordEnding();save();render();}else toast(r.message);}break;case'share':await doShare();break;case'poster':b.disabled=true;try{const current=page==='record'?viewedRecord:run;const poster=await downloadPoster(current,getEnding(current),char(getEnding(current).characterId));posterURL=poster.url;modal(`<h2>你的人生，已落成一张签。</h2><p>已尝试保存到浏览器下载。也可以长按下图保存，或点击下载链接。</p><img alt="我的大明人生签海报" src="${poster.url}" style="display:block;width:100%;max-width:400px;margin:15px auto"><a class="btn primary" href="${poster.url}" download="大明人生签.png">下载 PNG 海报 ↓</a>`);toast('900 × 1200 人生签已生成。');}catch(e){console.error(e);toast('海报生成未完成，请重试或复制战报。');}finally{b.disabled=false;}break;case'select-link':$('.share-input').focus();$('.share-input').select();break;}
});

function syncAudio(){setAudioScene(page==='game'?(run?.phase==='ending'?'ending':run?.phase==='battle'?'battle':'story'):page==='record'?'ending':'menu');}
function formationPanel(){return `<div class="formation-section"><div class="section-label">布阵 · 决定此役攻守</div><div class="formation-grid">${Object.entries(FORMATIONS).map(([id,f])=>`<button class="formation ${run.formation===id||(!run.formation&&id==='balanced')?'selected':''}" data-formation="${id}" aria-pressed="${(run.formation||'balanced')===id}"><strong>${esc(f.name)}</strong><small>${esc(f.description)}</small></button>`).join('')}</div></div>`;}
function objectivePanel(b){if(!b.objective)return '';const o=b.objective;return `<div class="objective ${o.complete?'complete':''}"><div><b>${o.complete?'✦':'◇'} ${esc(o.title)}</b><span>${Math.min(o.progress,o.target)} / ${o.target}</span></div><p>${esc(o.description)}</p><div class="meter"><i style="width:${Math.min(100,o.progress/o.target*100)}%"></i></div></div>`;}
function abilityPanel(){if(run.ruleset!==2)return '';const a=getCompanionAbility(run);if(!a)return '';return `<button class="ability-button ${a.ready?'ready':''}" data-action="ability" ${!a.ready?'disabled':''}><span class="ability-glyph">策</span><span><strong>${esc(a.name)} <small>${a.used?'本战已用':a.ready?'已蓄势 · 施展':'蓄势 '+a.charge+' / '+a.maxCharge}</small></strong><small>${esc(a.description)}</small></span><span class="ability-key">F</span></button>`;}
function showCombatFeedback(r){const panel=$('#scene');if(!panel)return;const el=document.createElement('div');el.className='combat-feedback';el.textContent=r.type==='ability'?(r.message||'故人助阵'):r.damage!==undefined?`${r.counter?'克制！ ':''}击破 ${r.damage} · 损耗 ${r.incoming??0}`:(r.message||'故人助阵');panel.append(el);setTimeout(()=>el.remove(),1500);}
function showResourceFeedback(changes){Object.entries(changes).forEach(([key,n])=>{if(!n)return;const idx=Object.keys(names).indexOf(key),target=$('#stats .stats')?.children[idx];if(!target)return;const el=document.createElement('span');el.className='stat-change '+(n<0?'negative':'');el.textContent=(n>0?'+':'')+n;target.append(el);setTimeout(()=>el.remove(),1400);});}
function pauseGame(){if(page!=='game'||run?.phase==='ending')return;paused=true;setAudioPaused(true);pauseScene(true);modal(`<div class="eyebrow">长卷暂歇</div><h2>风云不急，等你归来。</h2><p>当前进度已自动保存。游戏画面与配乐已暂停。</p><div class="pause-actions"><button class="btn primary" data-action="close-modal">继续这一程 →</button><button class="btn" data-action="save-exit">存卷回首页</button><button class="btn" data-action="start">另起一卷</button></div>`);save();}
function audioSettings(){const a=getAudioSettings();modal(`<div class="eyebrow">听山河 · 原创配乐</div><h2>把风声，调到刚刚好。</h2><div class="audio-row"><label><input type="checkbox" data-audio="musicEnabled" ${a.musicEnabled?'checked':''}> 背景音乐</label><span id="music-percent">${Math.round(a.musicVolume*100)}%</span><input aria-label="背景音乐音量" data-audio="musicVolume" type="range" min="0" max="100" value="${Math.round(a.musicVolume*100)}"></div><div class="audio-row"><label><input type="checkbox" data-audio="sfxEnabled" ${a.sfxEnabled?'checked':''}> 操作与战斗音效</label><span id="sfx-percent">${Math.round(a.sfxVolume*100)}%</span><input aria-label="音效音量" data-audio="sfxVolume" type="range" min="0" max="100" value="${Math.round(a.sfxVolume*100)}"></div><p class="audio-status" id="audio-status" role="status"></p><p class="game-hint">配乐随菜单、行旅、战役与结局转换；设置会保存在当前浏览器。</p><button class="btn primary" data-action="close-modal">听着山河，继续 →</button>`);function refreshStatus(){const t=$('#audio-status');if(!t)return;const a=getAudioSettings(),status=getAudioStatus();t.textContent=!a.musicEnabled?'背景音乐已静音':status.paused||status.hidden?'配乐已暂歇':status.playing?'配乐正在演奏 · '+({menu:'长卷初启',story:'故人行旅',battle:'旌旗风起',ending:'山河回响'}[status.scene]||''):'配乐待启 · 点击页面后自动开始';t.dataset.playing=String(status.playing);t.dataset.contextState=status.contextState;t.dataset.schedulerCount=String(status.schedulerCount);t.dataset.voices=String(status.activeMusicVoices);t.dataset.outputLevel=String(status.outputLevel);t.dataset.notesScheduled=String(status.notesScheduled);}refreshStatus();audioStatusTimer=setInterval(refreshStatus,500);}
document.addEventListener('input',event=>{const el=event.target;if(!el.dataset.audio)return;const key=el.dataset.audio,value=el.type==='checkbox'?el.checked:Number(el.value)/100;setAudioSetting(key,value);const music=$('[data-action="sound"]');if(music){music.textContent=soundEnabled()?'♪':'♩';music.classList.toggle('music-on',soundEnabled());}if(key.endsWith('Volume')){const out=$(key==='musicVolume'?'#music-percent':'#sfx-percent');if(out)out.textContent=el.value+'%';}});
document.addEventListener('keydown',event=>{if(event.repeat||event.ctrlKey||event.metaKey||event.altKey||/INPUT|TEXTAREA|SELECT/.test(event.target.tagName))return;if(event.key==='Escape'){if($('#modal').open){event.preventDefault();closeModal();}else{event.preventDefault();pauseGame();}return;}if($('#modal').open||paused||page!=='game'||run?.phase!=='battle')return;const key=event.key.toLowerCase();if(['1','2','3'].includes(key)){event.preventDefault();selectLane(Number(key)-1);}const t={q:'strike',w:'guard',e:'flank',r:'volley'}[key];if(t){event.preventDefault();perform(()=>actBattle(run,t,run.selectedLane??1));}if(key==='f'){event.preventDefault();perform(()=>useCompanionAbility(run));}});
$('#modal').addEventListener('cancel',event=>{event.preventDefault();closeModal();});
document.addEventListener('visibilitychange',()=>pauseScene(document.hidden||paused));

$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal();});
initAudio();
render();
if(challengeSeed)setTimeout(()=>toast('收到一枚同题种子，点击「接受好友同题」开始。'),600);
if(!saveAvailable)setTimeout(()=>toast('本浏览器存档不可用，请保持页面开启以保留进度。'),1000);
